import com.holdmyspot.codexunleashed.scheduler.SwapRecovery;

/**
 * Exercises actual history updates without sampling or controlling native processes.
 */
class SwapRecoveryProbe
{
    /**
     * Checks growth, latched pressure, relief, invalid reads and exact long boundaries.
     *
     * @param arguments unused
     */
    public static void main(String[] arguments)
    {
        var history = new SwapRecovery();
        check(history.observe(100, true), false, "first occupied sample");
        check(history.observe(101, true), true, "observed swap growth");
        check(history.observe(101, true), true, "unchanged occupancy with pressure");
        check(history.observe(101, false), false, "pressure relief without swap decrease");
        check(history.observe(101, true), false, "old occupancy after recovery");
        check(history.observe(102, false), true, "growth before pressure");
        try
        {
            history.observe(-1, false);
            throw new AssertionError("negative sample accepted");
        }
        catch (IllegalArgumentException expected)
        {
            System.out.println("negative sample rejected");
        }
        check(history.observe(102, true), true, "invalid sample preserved history");
        check(history.observe(0, false), false, "occupancy reset without pressure");
        check(history.observe(Long.MAX_VALUE, true), true, "exact large growth");
        check(history.observe(Long.MAX_VALUE, false), false, "large occupancy with relief");
    }

    /**
     * Checks and prints the public operation's decision.
     *
     * @param actual the observed incident state
     * @param expected the required incident state
     * @param name the represented sample transition
     */
    private static void check(boolean actual, boolean expected, String name)
    {
        if (actual != expected)
            throw new AssertionError(name + ": expected " + expected + ", observed " + actual);
        System.out.println(name + "=" + actual);
    }
}
